{
  "type": "科学植物信息图海报",
  "subject": "{argument name=\"plant species\" default=\"Pomegranate (Punica granatum)\"}",
  "style": "复古植物插画结合现代信息图，高细节，{argument name=\"color palette\" default=\"earthy greens, deep reds, parchment background\"}",
  "header": {
    "main_title": "{argument name=\"main title\" default=\"植物生命路径剖面\"}",
    "english_title": "{argument name=\"english title\" default=\"BOTANICAL GROWTH ATLAS\"}",
    "subtitle": "从种子到果实，一株植物如何展开自己 / FROM SEED TO FRUIT"
  },
  "centerpiece": "完整植物，广泛根系、木质茎、绿叶、盛开红花、熟果，其中一个切半露籽",
  "layout": {
    "numbered_sections": [
      {
        "number": 1,
        "title": "种子结构 / Seed Architecture",
        "content": "单籽剖面，6个标注部件"
      },
      {
        "number": 2,
        "title": "萌发机制 / Germination Mechanism",
        "content": "5颗萌发种子序列，展示胚根出现"
      },
      {
        "number": 3,
        "title": "根系与地下网络 / Root System + Subsurface Intelligence",
        "content": "细致根网，2个圆形显微剖面展示维管束和菌丝"
      },
      {
        "number": 4,
        "title": "茎叶生长与维管系统 / Stem, Leaf & Vascular System",
        "content": "叶细节和圆形茎剖面，5个标注层"
      },
      {
        "number": 5,
        "title": "光合作用与能量转换 / Photosynthesis + Energy Conversion",
        "content": "3D叶细胞剖面，展示叶肉和叶绿体，另附化学方程式图"
      },
      {
        "number": 6,
        "title": "花芽分化与开花机制 / Bud Formation + Blooming",
        "content": "细致花剖面，显示雄蕊和子房，加4季时间线"
      },
      {
        "number": 7,
        "title": "授粉与结果路径 / Pollination + Fruiting Pathway",
        "content": "蜜蜂接近花剖面，随后5阶段展示子房发育成果实"
      },
      {
        "number": 8,
        "title": "果实成熟与种子循环 / Fruit Maturation + Seed Cycle",
        "content": "熟果裂开，种子向下散落至新芽"
      }
    ],
    "additional_elements": [
      {
        "position": "左下",
        "title": "环境触发因素 / Environmental Triggers",
        "content": "6个天气/环境图标和6个营养元素图标(N, P, K, Ca, Mg, Fe)的网格"
      },
      {
        "position": "底边",
        "title": "Growth Timeline",
        "content": "19个小植物图标的线性序列，显示从种子到成株完整生命周期"
      }
    ],
    "footer_quote": "{argument name=\"bottom quote\" default=\"理解植物，就是理解生命如何在时间中构建秩序。\"}"
  }
}

