prm_a28ee82cb9db59458639983f2711c874.text:
{
  "type": "双页漫画跨页",
  "style": "高度细致的写实漫画、单色、网点、戏剧性光照、心理惊悚",
  "global_elements": {
    "protagonist": "{argument name=\"main character description\" default=\"young Japanese salaryman in a suit\"}",
    "theme": "{argument name=\"core concept\" default=\"surrounded by a massive crowd of identical clones of himself\"}"
  },
  "layout": {
    "left_page": {
      "type": "整页大幅画格",
      "setting": "{argument name=\"setting\" default=\"Shibuya scramble crossing at night\"}",
      "visuals": "主角独自站在十字路口中央，惊愕地环顾庞大人群，其中每个人都是与他完全相同的克隆人。",
      "text_elements": [
        {
          "type": "漫画标题标志",
          "text": "{argument name=\"manga title\" default=\"俺だらけの街\"}"
        },
        {
          "type": "副标题",
          "text": "第1話 交代"
        },
        {
          "type": "旁白框",
          "text": "その夜、世界は静かに俺をやめた。"
        },
        {
          "type": "音效",
          "text": "ザワ…"
        }
      ]
    },
    "right_page": {
      "type": "5格纵向布局",
      "panels": [
        {
          "panel_number": 1,
          "visuals": "主角眼睛的极近特写，因震惊而睁大，冒着汗。",
          "text_elements": [
            {
              "type": "对话气泡",
              "text": "……は？ なんで……みんな、俺なんだ？"
            },
            {
              "type": "音效",
              "text": "ドクン"
            }
          ]
        },
        {
          "panel_number": 2,
          "visuals": "横向一排8名身穿西装、完全相同的克隆人，面无表情地直视前方。",
          "text_elements": [
            {
              "type": "音效",
              "text": "ザワ…"
            }
          ]
        },
        {
          "panel_number": 3,
          "visuals": "一个克隆人凑近，在震惊的主角耳边低语。",
          "text_elements": [
            {
              "type": "对话气泡",
              "text": "お前の代わりは、もう足りてる。"
            },
            {
              "type": "音效",
              "text": "スッ"
            }
          ]
        },
        {
          "panel_number": 4,
          "visuals": "一只手握着智能手机，屏幕特写显示一条推送通知。",
          "text_elements": [
            {
              "type": "屏幕文字",
              "text": "交代を開始します。"
            },
            {
              "type": "音效",
              "text": "ピロン"
            }
          ]
        },
        {
          "panel_number": 5,
          "visuals": "城市街道上无尽克隆人群的广角镜头。",
          "text_elements": [
            {
              "type": "旁白框",
              "text": "最初に消えるのは、名前でも命でもない。居場所だ。"
            },
            {
              "type": "左下角文字",
              "text": "俺は、ここにいていいのか——？"
            },
            {
              "type": "右下角文字",
              "text": "{argument name=\"cliffhanger text\" default=\"次号へつづく！\"}"
            },
            {
              "type": "音效",
              "text": "ザワ… ザワ… ザワ…"
            }
          ]
        }
      ]
    }
  }
}

